<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { ElMessage,ElMessageBox,type FormInstance,type FormRules } from 'element-plus';import { BellRing,Edit3,Eye,Plus,Trash2,Wrench } from 'lucide-vue-next';import ResourceState from '@/components/common/ResourceState.vue';import { createDevice,deleteDevice,getDeviceDetail,getDeviceRecords,updateDevice,type DevicePayload,type DeviceRecordRaw } from '@/api/device';import { getProjectList,type ProjectRecord } from '@/api/project';import { hasPermission } from '@/api/permission'
const data=ref<DeviceRecordRaw[]>([]),projects=ref<ProjectRecord[]>([]),loading=ref(false),error=ref(''),dialog=ref(false),detailDialog=ref(false),saving=ref(false),detail=ref<DeviceRecordRaw>(),page=ref(1),size=ref(10),keyword=ref(''),type=ref(''),status=ref('');const formRef=ref<FormInstance>();const blank=():DevicePayload=>({deviceCode:'',deviceName:'',projectId:0,deviceType:'',manufacturer:'',model:'',installationLocation:'',status:'OFFLINE',installedAt:'',remark:''});const form=ref<DevicePayload>(blank());const rules:FormRules={deviceCode:[{required:true,message:'请输入设备编号'}],deviceName:[{required:true,message:'请输入设备名称'}],projectId:[{required:true,message:'请选择项目'}],deviceType:[{required:true,message:'请选择设备类型'}]};const filtered=computed(()=>data.value.filter(x=>(!keyword.value||`${x.deviceName}${x.deviceCode}`.includes(keyword.value))&&(!type.value||x.deviceType===type.value)&&(!status.value||x.status===status.value)));const rows=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value));const projectName=(id:number)=>projects.value.find(x=>x.id===id)?.projectName||`项目 ${id}`;const load=async()=>{loading.value=true;error.value='';try{const [d,p]=await Promise.all([getDeviceRecords(),getProjectList()]);data.value=d.data;projects.value=p.data}catch(e){error.value=e instanceof Error?e.message:'网络异常'}finally{loading.value=false}};const edit=(row?:DeviceRecordRaw)=>{form.value=row?{...row}:blank();dialog.value=true};const save=async()=>{if(!await formRef.value?.validate())return;saving.value=true;try{form.value.id?await updateDevice(form.value):await createDevice(form.value);ElMessage.success('设备保存成功');dialog.value=false;await load()}finally{saving.value=false}};const view=async(row:DeviceRecordRaw)=>{detail.value=(await getDeviceDetail(row.id)).data;detailDialog.value=true};const remove=async(row:DeviceRecordRaw)=>{await ElMessageBox.confirm(`确认停用并删除设备“${row.deviceName}”？`,'二次确认',{type:'warning'});await deleteDevice(row.id);ElMessage.success('设备已停用');await load()};onMounted(load)
</script>
<template><article class="tech-panel"><div class="panel-head"><h2 class="panel-title">设备档案管理</h2><button v-if="hasPermission('supervisor:device:add')" class="tech-button" @click="edit()"><Plus :size="14"/>新增设备</button></div><div class="resource-toolbar"><el-input v-model="keyword" clearable placeholder="设备名称 / 编号"/><el-select v-model="type" clearable placeholder="设备类型"><el-option label="塔吊" value="TOWER_CRANE"/><el-option label="环境监测" value="DUST"/><el-option label="升降机" value="ELEVATOR"/></el-select><el-select v-model="status" clearable placeholder="在线状态"><el-option label="在线" value="ONLINE"/><el-option label="离线" value="OFFLINE"/><el-option label="报警" value="ALARM"/></el-select><button class="tech-button secondary" @click="load">查询</button></div><ResourceState :loading="loading" :error="error" :empty="!rows.length" @retry="load"><el-table :data="rows"><el-table-column prop="deviceCode" label="设备编号"/><el-table-column prop="deviceName" label="设备名称" min-width="150"/><el-table-column prop="deviceType" label="设备类型"/><el-table-column label="所属项目"><template #default="{row}">{{ projectName(row.projectId) }}</template></el-table-column><el-table-column label="在线状态"><template #default="{row}"><span class="status-pill" :class="row.status==='ONLINE'?'status-running':row.status==='ALARM'?'status-alarm':'status-offline'">{{ row.status }}</span></template></el-table-column><el-table-column prop="manufacturer" label="生产厂家"/><el-table-column prop="installedAt" label="安装日期" min-width="150"/><el-table-column label="操作" width="270" fixed="right"><template #default="{row}"><el-button link @click="view(row)"><Eye :size="13"/>详情</el-button><el-button link @click="$router.push('/maintenance')"><Wrench :size="13"/>维护</el-button><el-button link @click="$router.push({path:'/alarms',query:{deviceId:row.id}})"><BellRing :size="13"/>报警</el-button><el-button v-if="hasPermission('supervisor:device:edit')" link @click="edit(row)"><Edit3 :size="13"/>修改</el-button><el-button v-if="hasPermission('supervisor:device:delete')" link type="danger" @click="remove(row)"><Trash2 :size="13"/>停用</el-button></template></el-table-column></el-table><div class="resource-pagination"><span>共 {{ filtered.length }} 台设备</span><el-pagination v-model:current-page="page" v-model:page-size="size" layout="prev,pager,next,sizes" :total="filtered.length"/></div></ResourceState></article><el-dialog v-model="dialog" :title="form.id?'修改设备':'新增设备'" width="min(760px,92vw)"><el-form ref="formRef" :model="form" :rules="rules" label-width="95px" class="dialog-form"><el-form-item label="设备编号" prop="deviceCode"><el-input v-model="form.deviceCode"/></el-form-item><el-form-item label="设备名称" prop="deviceName"><el-input v-model="form.deviceName"/></el-form-item><el-form-item label="所属项目" prop="projectId"><el-select v-model="form.projectId"><el-option v-for="p in projects" :key="p.id" :label="p.projectName" :value="p.id"/></el-select></el-form-item><el-form-item label="设备类型" prop="deviceType"><el-select v-model="form.deviceType"><el-option label="塔吊" value="TOWER_CRANE"/><el-option label="升降机" value="ELEVATOR"/><el-option label="环境监测" value="DUST"/></el-select></el-form-item><el-form-item label="生产厂家"><el-input v-model="form.manufacturer"/></el-form-item><el-form-item label="设备型号"><el-input v-model="form.model"/></el-form-item><el-form-item label="安装位置"><el-input v-model="form.installationLocation"/></el-form-item><el-form-item label="设备状态"><el-select v-model="form.status"><el-option label="在线" value="ONLINE"/><el-option label="离线" value="OFFLINE"/><el-option label="报警" value="ALARM"/></el-select></el-form-item><el-form-item label="安装时间"><el-date-picker v-model="form.installedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark"/></el-form-item></el-form><template #footer><button class="tech-button secondary" @click="dialog=false">取消</button><button class="tech-button" :disabled="saving" @click="save">{{ saving?'保存中...':'保存' }}</button></template></el-dialog><el-dialog v-model="detailDialog" title="设备详情" width="min(720px,92vw)"><div v-if="detail" class="detail-grid"><div v-for="(value,key) in detail" :key="key"><small>{{ key }}</small><b>{{ value??'—' }}</b></div></div></el-dialog></template>
<style scoped>.resource-toolbar{display:grid;grid-template-columns:1.4fr 1fr 1fr auto;gap:8px;padding:12px}.resource-pagination{display:flex;justify-content:space-between;padding:10px;color:#6f8da9}.dialog-form,.detail-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:2px}.detail-grid{gap:8px}.detail-grid>div{padding:9px;border:1px solid rgba(79,168,255,.13);border-radius:5px;background:rgba(9,31,56,.5)}.detail-grid small{display:block;color:#6584a0}.detail-grid b{display:block;margin-top:5px;color:#d6e8f6;font-size:10px}@media(max-width:700px){.resource-toolbar,.dialog-form,.detail-grid{grid-template-columns:1fr}}</style>

